+import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
+import { join } from "node:path";
+import type { I18nSourceEntry, RawI18nSource } from "@pantoken/translation-adapters";
+
+const docsRoot = join(import.meta.dirname, "..");
+const demosDir = join(docsRoot, "demos");
+const PLACEHOLDER = /{{([a-z][\w-]*)}}/gu;
+
+function surroundingWhitespace(source: string): { leading: string; text: string; trailing: string } {
+  const leading = source.match(/^\s*/u)?.[0] ?? "";
+  const trailing = source.match(/\s*$/u)?.[0] ?? "";
+  return { leading, text: source.slice(leading.length, source.length - trailing.length), trailing };
+}
+
+function classTokens(template: string): Set<string> {
+  return new Set(
+    [...template.matchAll(/\bclass\s*=\s*["']([^"']*)["']/gu)].flatMap((match) =>
+      match[1].split(/\s+/u).map((token) => token.replace(/^-+/u, "")),
+    ),
+  );
+}
+
+function isClassLabel(source: string, tokens: ReadonlySet<string>): boolean {
+  const labels = source.split(/\s+/u);
+  return labels.length > 0 && labels.every((label) => tokens.has(label.replace(/^-+/u, "")));
+}
+
+function isCodeLabel(key: string, template: string): boolean {
+  return new RegExp(`<code\\b[^>]*>[\\s\\S]*?{{${key}}}[\\s\\S]*?</code>`, "u").test(template);
+}
+
+function sourceValue(entry: I18nSourceEntry): string {
+  return typeof entry === "string" ? entry : entry.string;
+}
+
+function withRequiredVerbatim(entry: I18nSourceEntry, string: string): I18nSourceEntry {
+  return typeof entry === "string" ? { string, verbatim: "required" } : { ...entry, string, verbatim: "required" };
+}
+
+for (const directory of readdirSync(demosDir, { withFileTypes: true })) {
+  if (!directory.isDirectory()) continue;
+  const demoDir = join(demosDir, directory.name);
+  const jsonPath = join(demoDir, "i18n.json");
+  const files = ["index.html", "style.css", "script.js"].filter((file) =>
+    existsSync(join(demoDir, file)),
+  );
+  const templates = new Map(files.map((file) => [file, readFileSync(join(demoDir, file), "utf8")]));
+  const template = templates.get("index.html") ?? "";
+  const tokens = classTokens(template);
+  const raw = JSON.parse(readFileSync(jsonPath, "utf8")) as RawI18nSource;
+  let changed = false;
+
+  for (const [key, entry] of Object.entries(raw)) {
+    const source = sourceValue(entry);
+    const { leading, text, trailing } = surroundingWhitespace(source);
+    if (source !== text) {
+      raw[key] = typeof entry === "string" ? text : { ...entry, string: text };
+      for (const [file, content] of templates) {
+        templates.set(file, content.replaceAll(`{{${key}}}`, `${leading}{{${key}}}${trailing}`));
+      }
+      changed = true;
+    }
+    if (isCodeLabel(key, template) || isClassLabel(text, tokens)) {
+      raw[key] = withRequiredVerbatim(raw[key], text);
+      changed = true;
+    }
+  }
+
+  if (!changed) continue;
+  writeFileSync(jsonPath, `${JSON.stringify(raw, null, 2)}\n`);
+  for (const [file, content] of templates) writeFileSync(join(demoDir, file), content);
+  console.log(`✓ normalized demos/${directory.name}/i18n.json`);
+}
